
import Backbone from 'backbone';
import { map, extend } from 'lodash-es';
import Commit from '../models/commit';

const Commits = Backbone.Collection.extend({
  model: Commit,

  initialize: function(models, options) {
    this.repo = options.repo;
  },

  setBranch: function(branch, options) {
    this.branch = branch;
    this.fetch(options);
  },

  parse: function(resp, options) {
    return map(resp, (function(commit) {
      return  extend(commit, {
        repo: this.repo
      });
    }).bind(this));
  },

  url: function() {
    return this.repo.url() + '/commits?sha=' + this.branch;
  }
});

export default Commits;
